export function BrowseBinStoresByStateSection() {
  const active = binStoresByState.filter((s) => s.hasCoverage && s.count > 0);

  return (
    <section id="browse-states" className="py-24 bg-muted/30">
      <div className="mx-auto max-w-7xl px-6">
        <div className="text-center max-w-2xl mx-auto mb-14">
          <div className="text-xs uppercase tracking-[0.2em] text-mint mb-3">
            Browse the directory
          </div>
          <h2 className="font-display text-3xl md:text-4xl font-semibold tracking-tight">
            Bin stores by state
          </h2>
          <p className="mt-3 text-muted-foreground leading-relaxed">
            Select a state to see Amazon liquidation-style bin stores, overstock warehouses, and
            daily deal bins near you.
          </p>
        </div>
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3 sm:gap-4">
          {active.map((s, i) => (
            <motion.a
              key={s.slug}
              href={territoryHref(s.slug)}
              initial={{ opacity: 0, y: 12 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: Math.min(i * 0.02, 0.4) }}
              className="group flex flex-col items-center justify-center p-5 rounded-2xl bg-card border border-border text-center hover-lift hover:border-mint/50 shadow-card"
            >
              <span className="font-display text-3xl font-bold text-gradient-mint mb-1">
                {s.count}
              </span>
              <span className="text-sm font-semibold text-foreground group-hover:text-mint transition-colors">
                Bin store{s.count !== 1 ? "s" : ""} in {s.name}
              </span>
            </motion.a>
          ))}
        </div>
      </div>
    </section>
  );
}

